using Microsoft.Azure.WebJobs;
using Microsoft.Extensions.Logging;
using Microsoft.Azure.EventGrid.Models;

public static class EventGridHandler
{
    [FunctionName("EventGridHandler")]
    public static void Run(
        [EventGridTrigger] EventGridEvent[] events,
        ILogger log)
    {
        foreach (var evt in events)
        {
            log.LogInformation($"Event: {evt.EventType}, Subject: {evt.Subject}");

            if (evt.EventType == "Microsoft.Storage.BlobCreated")
            {
                var data = evt.Data.ToObjectFromJson<StorageBlobCreatedEventData>();
                log.LogInformation($"Blob URL: {data.Url}");
                // Process the blob
            }
        }
    }
}

module.exports = async function (context, eventGridEvents) {
  for (const event of eventGridEvents) {
    context.log(`Event type: ${event.eventType}`);
    context.log(`Subject: ${event.subject}`);
    context.log(`Data: ${JSON.stringify(event.data)}`);

    if (event.eventType === "order.created") {
      await processNewOrder(event.data);
    }
  }
};
